import { WrapperConfig } from '../types';

/**
 * Generate native C++ Win32 WebView2 Project Files
 */
export function generateCppWebView2Project(config: WrapperConfig): Record<string, string> {
  const { app, window, native } = config;
  const isDark = window.darkTitleBar ? "TRUE" : "FALSE";
  const isFrameless = window.style === 'frameless';

  const mainCpp = `// ============================================================================
// ${app.name} - Native Windows Win32 WebView2 Application
// Generated by WebToExe Native Desktop Wrapper & PE Header Studio
// ============================================================================

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <dwmapi.h>
#include <shellapi.h>
#include <wrl.h>
#include <wil/com.h>
#include "WebView2.h"
#include "resource.h"
#include <string>

#pragma comment(lib, "dwmapi.lib")
#pragma comment(lib, "shell32.lib")
#pragma comment(lib, "user32.lib")
#pragma comment(lib, "gdi32.lib")

using namespace Microsoft::WRL;

// Configuration Constants
const wchar_t* APP_TITLE = L"${app.name.replace(/"/g, '\\"')}";
const wchar_t* WINDOW_CLASS = L"${app.executableName.replace(/\.exe$/i, '')}_WindowClass";
const wchar_t* TARGET_URL = L"${app.url.replace(/"/g, '\\"')}";
const wchar_t* CUSTOM_USER_AGENT = L"${(native.customUserAgent || '').replace(/"/g, '\\"')}";
const int DEFAULT_WIDTH = ${window.width};
const int DEFAULT_HEIGHT = ${window.height};
const int MIN_WIDTH = ${window.minWidth};
const int MIN_HEIGHT = ${window.minHeight};

// Global Pointers
HINSTANCE g_hInstance = nullptr;
HWND g_hWnd = nullptr;
wil::com_ptr<ICoreWebView2Controller> g_controller;
wil::com_ptr<ICoreWebView2> g_webview;
NOTIFYICONDATAW g_nid = { sizeof(NOTIFYICONDATAW) };

// Function Prototypes
LRESULT CALLBACK WndProc(HWND, UINT, WPARAM, LPARAM);
void InitializeWebView(HWND hWnd);
void SetupSystemTray(HWND hWnd);
void RemoveSystemTray();

int WINAPI wWinMain(HINSTANCE hInstance, HINSTANCE, PWSTR, int nCmdShow) {
    g_hInstance = hInstance;

    // Single Instance Check
    ${native.singleInstanceLock ? `
    HANDLE hMutex = CreateMutexW(nullptr, TRUE, L"${app.guid}");
    if (GetLastError() == ERROR_ALREADY_EXISTS) {
        HWND existingWnd = FindWindowW(WINDOW_CLASS, APP_TITLE);
        if (existingWnd) {
            ShowWindow(existingWnd, SW_RESTORE);
            SetForegroundWindow(existingWnd);
        }
        return 0;
    }
    ` : ''}

    // Register Window Class
    WNDCLASSEXW wcex = { sizeof(WNDCLASSEXW) };
    wcex.style = CS_HREDRAW | CS_VREDRAW;
    wcex.lpfnWndProc = WndProc;
    wcex.hInstance = hInstance;
    wcex.hIcon = LoadIconW(hInstance, MAKEINTRESOURCEW(IDI_APP_ICON));
    wcex.hCursor = LoadCursorW(nullptr, IDC_ARROW);
    wcex.hbrBackground = (HBRUSH)(COLOR_WINDOW + 1);
    wcex.lpszClassName = WINDOW_CLASS;
    wcex.hIconSm = LoadIconW(hInstance, MAKEINTRESOURCEW(IDI_APP_ICON));

    if (!RegisterClassExW(&wcex)) {
        MessageBoxW(nullptr, L"Failed to register window class", L"Error", MB_ICONERROR);
        return 1;
    }

    // Compute Window Style & Dimensions
    DWORD style = WS_OVERLAPPEDWINDOW;
    ${isFrameless ? 'style = WS_POPUP | WS_THICKFRAME | WS_MINIMIZEBOX | WS_MAXIMIZEBOX;' : ''}
    ${window.alwaysOnTop ? 'DWORD exStyle = WS_EX_TOPMOST;' : 'DWORD exStyle = 0;'}

    RECT rc = { 0, 0, DEFAULT_WIDTH, DEFAULT_HEIGHT };
    AdjustWindowRectEx(&rc, style, FALSE, exStyle);

    int posX = ${window.centerScreen ? '(GetSystemMetrics(SM_CXSCREEN) - (rc.right - rc.left)) / 2' : 'CW_USEDEFAULT'};
    int posY = ${window.centerScreen ? '(GetSystemMetrics(SM_CYSCREEN) - (rc.bottom - rc.top)) / 2' : 'CW_USEDEFAULT'};

    g_hWnd = CreateWindowExW(
        exStyle,
        WINDOW_CLASS,
        APP_TITLE,
        style,
        posX, posY,
        rc.right - rc.left, rc.bottom - rc.top,
        nullptr, nullptr, hInstance, nullptr
    );

    if (!g_hWnd) return 1;

    // Apply Windows 11 / 10 Dark Mode & Immersive Attributes
    BOOL useDarkMode = ${isDark};
    DwmSetWindowAttribute(g_hWnd, 20 /* DWMWA_USE_IMMERSIVE_DARK_MODE */, &useDarkMode, sizeof(useDarkMode));

    ${window.style === 'mica' ? `
    // Enable Windows 11 Mica backdrop material
    int micaType = 2; // DWMSBT_MAINWINDOW
    DwmSetWindowAttribute(g_hWnd, 38 /* DWMWA_SYSTEMBACKDROP_TYPE */, &micaType, sizeof(micaType));
    ` : ''}

    ${native.enableSystemTray ? 'SetupSystemTray(g_hWnd);' : ''}

    int finalShowCmd = nCmdShow;
    ${window.initialState === 'maximized' ? 'finalShowCmd = SW_MAXIMIZE;' : ''}
    ${window.initialState === 'fullscreen' || window.initialState === 'kiosk' ? `
    SetWindowLongPtrW(g_hWnd, GWL_STYLE, WS_POPUP | WS_VISIBLE);
    SetWindowPos(g_hWnd, HWND_TOP, 0, 0, GetSystemMetrics(SM_CXSCREEN), GetSystemMetrics(SM_CYSCREEN), SWP_FRAMECHANGED);
    finalShowCmd = SW_SHOW;
    ` : ''}

    ShowWindow(g_hWnd, finalShowCmd);
    UpdateWindow(g_hWnd);

    // Initialize Microsoft Edge WebView2 Control
    InitializeWebView(g_hWnd);

    // Message Loop
    MSG msg;
    while (GetMessageW(&msg, nullptr, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

    ${native.enableSystemTray ? 'RemoveSystemTray();' : ''}
    return (int)msg.wParam;
}

void InitializeWebView(HWND hWnd) {
    CreateCoreWebView2EnvironmentWithOptions(
        nullptr, nullptr, nullptr,
        Callback<ICoreWebView2CreateCoreWebView2EnvironmentCompletedHandler>(
            [hWnd](HRESULT result, ICoreWebView2Environment* env) -> HRESULT {
                if (FAILED(result)) return result;

                env->CreateCoreWebView2Controller(hWnd,
                    Callback<ICoreWebView2CreateCoreWebView2ControllerCompletedHandler>(
                        [hWnd](HRESULT result, ICoreWebView2Controller* controller) -> HRESULT {
                            if (FAILED(result)) return result;

                            g_controller = controller;
                            g_controller->get_CoreWebView2(&g_webview);

                            // Resize WebView to match Client Window Area
                            RECT bounds;
                            GetClientRect(hWnd, &bounds);
                            g_controller->put_Bounds(bounds);

                            // Configure Settings
                            wil::com_ptr<ICoreWebView2Settings> settings;
                            g_webview->get_Settings(&settings);
                            if (settings) {
                                settings->put_AreDevToolsEnabled(${native.enableDevTools ? 'TRUE' : 'FALSE'});
                                settings->put_AreDefaultContextMenusEnabled(${native.enableContextMenu ? 'TRUE' : 'FALSE'});
                                settings->put_IsStatusBarEnabled(FALSE);
                                settings->put_IsZoomControlEnabled(TRUE);
                            }

                            // Inject Custom Stylesheet
                            ${native.customCss ? `
                            std::wstring css = LR"raw(${native.customCss})raw";
                            std::wstring script = L"const style = document.createElement('style'); style.textContent = \`" + css + L"\`; document.head.appendChild(style);";
                            g_webview->AddScriptToExecuteOnDocumentCreated(script.c_str(), nullptr);
                            ` : ''}

                            // Inject Custom JavaScript
                            ${native.customJs ? `
                            std::wstring js = LR"raw(${native.customJs})raw";
                            g_webview->AddScriptToExecuteOnDocumentCreated(js.c_str(), nullptr);
                            ` : ''}

                            // Navigate to target URL
                            g_webview->Navigate(TARGET_URL);
                            return S_OK;
                        }).Get());
                return S_OK;
            }).Get());
}

void SetupSystemTray(HWND hWnd) {
    g_nid.hWnd = hWnd;
    g_nid.uID = 1001;
    g_nid.uFlags = NIF_ICON | NIF_MESSAGE | NIF_TIP;
    g_nid.uCallbackMessage = WM_APP + 1;
    g_nid.hIcon = LoadIconW(g_hInstance, MAKEINTRESOURCEW(IDI_APP_ICON));
    wcsncpy_s(g_nid.szTip, APP_TITLE, _TRUNCATE);
    Shell_NotifyIconW(NIM_ADD, &g_nid);
}

void RemoveSystemTray() {
    Shell_NotifyIconW(NIM_DELETE, &g_nid);
}

LRESULT CALLBACK WndProc(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam) {
    switch (message) {
    case WM_SIZE:
        if (g_controller) {
            RECT bounds;
            GetClientRect(hWnd, &bounds);
            g_controller->put_Bounds(bounds);
        }
        ${native.minimizeToTray ? `
        if (wParam == SIZE_MINIMIZED && ${native.enableSystemTray ? 'true' : 'false'}) {
            ShowWindow(hWnd, SW_HIDE);
            return 0;
        }
        ` : ''}
        break;

    case WM_GETMINMAXINFO: {
        LPMINMAXINFO lpMMI = (LPMINMAXINFO)lParam;
        lpMMI->ptMinTrackSize.x = MIN_WIDTH;
        lpMMI->ptMinTrackSize.y = MIN_HEIGHT;
        ${window.maxWidth > 0 ? `lpMMI->ptMaxTrackSize.x = ${window.maxWidth};` : ''}
        ${window.maxHeight > 0 ? `lpMMI->ptMaxTrackSize.y = ${window.maxHeight};` : ''}
        return 0;
    }

    case WM_APP + 1: // System Tray Message
        if (lParam == WM_LBUTTONUP || lParam == WM_LBUTTONDBLCLK) {
            ShowWindow(hWnd, SW_SHOW);
            SetForegroundWindow(hWnd);
        }
        break;

    case WM_CLOSE:
        ${native.closeToTray ? `
        ShowWindow(hWnd, SW_HIDE);
        return 0;
        ` : `
        DestroyWindow(hWnd);
        break;
        `}

    case WM_DESTROY:
        PostQuitMessage(0);
        break;

    default:
        return DefWindowProcW(hWnd, message, wParam, lParam);
    }
    return 0;
}
`;

  const resourceH = `// resource.h - Symbols definition
#define IDI_APP_ICON 101
#define IDR_MANIFEST 1
`;

  const resourceRc = `// resource.rc - Application Resource Script
#include <windows.h>
#include "resource.h"

// Application Icon
IDI_APP_ICON ICON "app.ico"

// DPI and Windows Compatibility Manifest
IDR_MANIFEST RT_MANIFEST "app.manifest"

// Version Information
VS_VERSION_INFO VERSIONINFO
FILEVERSION ${app.version.replace(/\./g, ',')},0
PRODUCTVERSION ${app.version.replace(/\./g, ',')},0
FILEFLAGSMASK 0x3fL
FILEFLAGS 0x0L
FILEOS VOS__WINDOWS32
FILETYPE VFT_APP
FILESUBTYPE 0x0L
BEGIN
    BLOCK "StringFileInfo"
    BEGIN
        BLOCK "040904b0"
        BEGIN
            VALUE "CompanyName", "${app.company}\\0"
            VALUE "FileDescription", "${app.description}\\0"
            VALUE "FileVersion", "${app.version}\\0"
            VALUE "InternalName", "${app.executableName}\\0"
            VALUE "LegalCopyright", "${app.copyright}\\0"
            VALUE "OriginalFilename", "${app.executableName}\\0"
            VALUE "ProductName", "${app.name}\\0"
            VALUE "ProductVersion", "${app.version}\\0"
        END
    END
    BLOCK "VarFileInfo"
    BEGIN
        VALUE "Translation", 0x409, 1200
    END
END
`;

  const appManifest = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<assembly xmlns="urn:schemas-microsoft-com:asm.v1" manifestVersion="1.0">
  <assemblyIdentity version="${app.version}" processorArchitecture="*" name="${app.executableName}" type="win32"/>
  <description>${app.description}</description>
  <trustInfo xmlns="urn:schemas-microsoft-com:asm.v3">
    <security>
      <requestedPrivileges>
        <requestedExecutionLevel level="asInvoker" uiAccess="false"/>
      </requestedPrivileges>
    </security>
  </trustInfo>
  <application xmlns="urn:schemas-microsoft-com:asm.v3">
    <windowsSettings>
      <dpiAware xmlns="http://schemas.microsoft.com/SMI/2005/WindowsSettings">true/pm</dpiAware>
      <dpiAwareness xmlns="http://schemas.microsoft.com/SMI/2016/WindowsSettings">PerMonitorV2, PerMonitor</dpiAwareness>
      <longPathAware xmlns="http://schemas.microsoft.com/SMI/2016/WindowsSettings">true</longPathAware>
    </windowsSettings>
  </application>
  <compatibility xmlns="urn:schemas-microsoft-com:compatibility.v1">
    <application>
      <!-- Windows 10 and Windows 11 -->
      <supportedOS Id="{8e0f7a12-bfb3-4fe8-b9a5-48fd50a15a9a}"/>
    </application>
  </compatibility>
</assembly>
`;

  const cmakeLists = `cmake_minimum_required(VERSION 3.20)
project(${app.name.replace(/[^a-zA-Z0-9]/g, '_')} LANGUAGES CXX RC)

set(CMAKE_CXX_STANDARD 17)
set(CMAKE_CXX_STANDARD_REQUIRED ON)

add_executable(${app.name.replace(/[^a-zA-Z0-9]/g, '_')} WIN32
    main.cpp
    resource.rc
)

target_link_libraries(${app.name.replace(/[^a-zA-Z0-9]/g, '_')} PRIVATE
    dwmapi
    shell32
    user32
    gdi32
)
`;

  const buildBat = `@echo off
echo =======================================================
echo Building ${app.name} (${app.executableName})
echo =======================================================

where cl >nul 2>nul
if %ERRORLEVEL% NEQ 0 (
    echo MSVC cl.exe not found in PATH.
    echo Please open Developer Command Prompt for Visual Studio 2022.
    pause
    exit /b 1
)

rc /fo resource.res resource.rc
cl /O2 /EHsc /std:c++17 /Fe:${app.executableName} main.cpp resource.res /link /SUBSYSTEM:WINDOWS dwmapi.lib shell32.lib user32.lib gdi32.lib

if %ERRORLEVEL% EQU 0 (
    echo.
    echo [SUCCESS] Built ${app.executableName} successfully!
    echo Run .\\${app.executableName} to launch your native desktop application.
) else (
    echo.
    echo [ERROR] Compilation failed.
)
pause
`;

  return {
    "main.cpp": mainCpp,
    "resource.h": resourceH,
    "resource.rc": resourceRc,
    "app.manifest": appManifest,
    "CMakeLists.txt": cmakeLists,
    "build.bat": buildBat,
  };
}

/**
 * Generate C# .NET 8 / WPF WebView2 Solution
 */
export function generateCsharpWpfProject(config: WrapperConfig): Record<string, string> {
  const { app, window, native } = config;

  const csproj = `<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>WinExe</OutputType>
    <TargetFramework>net8.0-windows</TargetFramework>
    <Nullable>enable</Nullable>
    <UseWPF>true</UseWPF>
    <ApplicationIcon>app.ico</ApplicationIcon>
    <ApplicationManifest>app.manifest</ApplicationManifest>
    <AssemblyName>${app.executableName.replace(/\.exe$/i, '')}</AssemblyName>
    <AssemblyTitle>${app.name}</AssemblyTitle>
    <Company>${app.company}</Company>
    <Product>${app.name}</Product>
    <Copyright>${app.copyright}</Copyright>
    <Version>${app.version}</Version>
  </PropertyGroup>

  <ItemGroup>
    <PackageReference Include="Microsoft.Web.WebView2" Version="1.0.2592.51" />
  </ItemGroup>
</Project>`;

  const mainXaml = `<Window x:Class="NativeApp.MainWindow"
        xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        xmlns:wv2="clr-namespace:Microsoft.Web.WebView2.Wpf;assembly=Microsoft.Web.WebView2.Wpf"
        Title="${app.name}"
        Width="${window.width}"
        Height="${window.height}"
        MinWidth="${window.minWidth}"
        MinHeight="${window.minHeight}"
        WindowStartupLocation="${window.centerScreen ? 'CenterScreen' : 'Manual'}"
        Topmost="${window.alwaysOnTop}"
        WindowState="${window.initialState === 'maximized' ? 'Maximized' : 'Normal'}">
    <Grid>
        <wv2:WebView2 Name="webView" />
    </Grid>
</Window>`;

  const mainXamlCs = `using System;
using System.Windows;
using Microsoft.Web.WebView2.Core;

namespace NativeApp
{
    public partial class MainWindow : Window
    {
        public MainWindow()
        {
            InitializeComponent();
            Loaded += MainWindow_Loaded;
        }

        private async void MainWindow_Loaded(object sender, RoutedEventArgs e)
        {
            await webView.EnsureCoreWebView2Async();
            webView.CoreWebView2.Settings.AreDevToolsEnabled = ${native.enableDevTools};
            webView.CoreWebView2.Settings.AreDefaultContextMenusEnabled = ${native.enableContextMenu};

            ${native.customUserAgent ? `webView.CoreWebView2.Settings.UserAgent = "${native.customUserAgent.replace(/"/g, '\\"')}";` : ''}

            ${native.customCss ? `
            string css = @"${native.customCss.replace(/"/g, '""')}";
            string script = $"const s = document.createElement('style'); s.textContent = \`{css}\`; document.head.appendChild(s);";
            await webView.CoreWebView2.AddScriptToExecuteOnDocumentCreatedAsync(script);
            ` : ''}

            webView.Source = new Uri("${app.url}");
        }
    }
}`;

  return {
    [`${app.executableName.replace(/\.exe$/i, '')}.csproj`]: csproj,
    "MainWindow.xaml": mainXaml,
    "MainWindow.xaml.cs": mainXamlCs,
  };
}

/**
 * Generate Tauri 2.0 / Rust Native Desktop Project
 */
export function generateTauriProject(config: WrapperConfig): Record<string, string> {
  const { app, window, native } = config;

  const cargoToml = `[package]
name = "${app.name.toLowerCase().replace(/[^a-z0-9]/g, '-')}"
version = "${app.version}"
description = "${app.description}"
authors = ["${app.company}"]
edition = "2021"

[build-dependencies]
tauri-build = { version = "2.0", features = [] }

[dependencies]
tauri = { version = "2.0", features = ["tray-icon"] }
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
`;

  const tauriConf = JSON.stringify(
    {
      productName: app.name,
      version: app.version,
      identifier: `com.${app.company.toLowerCase().replace(/[^a-z0-9]/g, '')}.${app.name.toLowerCase().replace(/[^a-z0-9]/g, '')}`,
      build: {
        beforeDevCommand: "",
        beforeBuildCommand: "",
        devUrl: app.url,
      },
      app: {
        windows: [
          {
            title: app.name,
            width: window.width,
            height: window.height,
            minWidth: window.minWidth,
            minHeight: window.minHeight,
            resizable: window.resizable,
            fullscreen: window.initialState === 'fullscreen' || window.initialState === 'kiosk',
            alwaysOnTop: window.alwaysOnTop,
            center: window.centerScreen,
            url: app.url,
            decorations: window.style !== 'frameless',
          },
        ],
        security: {
          csp: null,
        },
      },
      bundle: {
        active: true,
        targets: "all",
        icon: ["icons/32x32.png", "icons/128x128.png", "icons/icon.ico"],
      },
    },
    null,
    2
  );

  const mainRs = `// Tauri 2.0 Native Wrapper Entry
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

fn main() {
    tauri::Builder::default()
        .setup(|app| {
            println!("Starting native desktop instance for ${app.name}");
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}
`;

  return {
    "Cargo.toml": cargoToml,
    "tauri.conf.json": tauriConf,
    "src-tauri/src/main.rs": mainRs,
  };
}

/**
 * Generate Inno Setup Windows Installer Script (.iss)
 */
export function generateInnoSetupScript(config: WrapperConfig): string {
  const { app } = config;

  return `; Inno Setup Installer Script for ${app.name}
; Compile with Inno Setup Compiler (ISCC.exe)

#define MyAppName "${app.name}"
#define MyAppVersion "${app.version}"
#define MyAppPublisher "${app.company}"
#define MyAppExeName "${app.executableName}"

[Setup]
AppId={{${app.guid}}}
AppName={#MyAppName}
AppVersion={#MyAppVersion}
AppPublisher={#MyAppPublisher}
DefaultDirName={autopf}\\{#MyAppName}
DefaultGroupName={#MyAppName}
AllowNoIcons=yes
OutputDir=Output
OutputBaseFilename=${app.executableName.replace(/\.exe$/i, '')}_Setup_v${app.version}
SetupIconFile=app.ico
Compression=lzma2/ultra64
SolidCompression=yes
WizardStyle=modern

[Languages]
Name: "english"; MessagesFile: "compiler:Default.isl"

[Tasks]
Name: "desktopicon"; Description: "{cm:CreateDesktopIcon}"; GroupDescription: "{cm:AdditionalIcons}"; Flags: unchecked

[Files]
Source: "${app.executableName}"; DestDir: "{app}"; Flags: ignoreversion
Source: "app.ico"; DestDir: "{app}"; Flags: ignoreversion

[Icons]
Name: "{group}\\{#MyAppName}"; Filename: "{app}\\{#MyAppExeName}"; IconFilename: "{app}\\app.ico"
Name: "{group}\\{cm:UninstallProgram,{#MyAppName}}"; Filename: "{uninstallexe}"
Name: "{autodesktop}\\{#MyAppName}"; Filename: "{app}\\{#MyAppExeName}"; Tasks: desktopicon; IconFilename: "{app}\\app.ico"

[Run]
Filename: "{app}\\{#MyAppExeName}"; Description: "{cm:LaunchProgram,{#StringChange(MyAppName, '&', '&&')}}"; Flags: nowait postinstall skipifsilent
`;
}

/**
 * Generate Zero-Dependency Standalone Windows Runner Script (.cmd)
 * Runs target URL in Microsoft Edge Native App Window mode without browser address bars!
 */
export function generatePortableBatchLauncher(config: WrapperConfig): string {
  const { app, window, native } = config;

  return `@echo off
:: ============================================================================
:: ${app.name} - Native Windows Standalone Launcher
:: Launches ${app.url} directly into a clean, dedicated native desktop window
:: ============================================================================
title ${app.name}
setlocal enabledelayedexpansion

set "TARGET_URL=${app.url}"
set "WINDOW_WIDTH=${window.width}"
set "WINDOW_HEIGHT=${window.height}"
set "DATA_DIR=%LOCALAPPDATA%\\${app.executableName.replace(/\.exe$/i, '')}\\Profile"

:: Locate Microsoft Edge or Chrome for Native App-Mode rendering
set "ENGINE_EXE="

if exist "%ProgramFiles(x86)%\\Microsoft\\Edge\\Application\\msedge.exe" (
    set "ENGINE_EXE=%ProgramFiles(x86)%\\Microsoft\\Edge\\Application\\msedge.exe"
) else if exist "%ProgramFiles%\\Microsoft\\Edge\\Application\\msedge.exe" (
    set "ENGINE_EXE=%ProgramFiles%\\Microsoft\\Edge\\Application\\msedge.exe"
) else if exist "%LocalAppData%\\Microsoft\\Edge\\Application\\msedge.exe" (
    set "ENGINE_EXE=%LocalAppData%\\Microsoft\\Edge\\Application\\msedge.exe"
) else if exist "%ProgramFiles%\\Google\\Chrome\\Application\\chrome.exe" (
    set "ENGINE_EXE=%ProgramFiles%\\Google\\Chrome\\Application\\chrome.exe"
)

if not defined ENGINE_EXE (
    start "" "%TARGET_URL%"
    exit /b 0
)

:: Launch with native app window switch (removes browser tabs, address bar, and search)
start "" "!ENGINE_EXE!" ^
    --app="%TARGET_URL%" ^
    --window-size=%WINDOW_WIDTH%,%WINDOW_HEIGHT% ^
    --user-data-dir="%DATA_DIR%" ^
    ${window.initialState === 'kiosk' ? '--kiosk' : ''} ^
    ${native.customUserAgent ? `--user-agent="${native.customUserAgent}"` : ''} ^
    --disable-features=Translate ^
    --no-first-run ^
    --no-default-browser-check

exit /b 0
`;
}
